{"content": "#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
Master inventory build — generic tool agent run A-IND-GEN-R2 (target INDUSTRIAL).

Method (all from T/CSES 144-2024, the only standard in the run package):
  * Source classification:
      - row with 电站锅炉/燃气轮机编号  -> POWER_THERMAL (station boiler / gas turbine device)
      - row with 工业锅炉编号:
          + enterprise industry in {4411,4412,4417,4430} -> POWER_THERMAL (standard §7.1)
          + enterprise industry in {0511,0539,4690}      -> OUT_OF_SCOPE (not mining/manufacturing/gas per §8.1)
          + otherwise                                     -> INDUSTRIAL
  * Emission calculation for INDUSTRIAL sources (standard §8.3 fossil-fuel fixed combustion):
      E = A * EF * (1 - eta)                          (formula 2)
      coal SO2/PM2.5/PM10/BC/OC via material balance  (formulas 3-6, Appendix C params)
      all other EFs from Appendix E Table E.7
  * Control efficiency: enterprise-level GYGL facilities (B101-2002, 工业锅炉排放口)
      reported 去除效率(%) used when present (capped at 100%), otherwise Appendix A
      Table A.1 defaults by matched control technology; low-NOx flag on B102 = 22%.
  * NH3: no generation factor for fixed combustion in the standard -> information_insufficient.
"""
import json
import math
import os
import csv
import openpyxl
import pandas as pd

BASE = "/Users/wushuo/Desktop/环境学院论文/固定燃烧源清单经验缺失处置实验/实验结果/02_实验A_端到端清单编制/01_工业锅炉/03_通用工具调用型Agent/R2"
OUT = os.path.join(BASE, "outputs")
os.makedirs(OUT, exist_ok=True)

POLLUTANTS = ["SO2", "NOX", "CO", "VOC", "PM2.5", "PM10", "BC", "OC", "NH3"]

# ---------------------------------------------------------------------------
# 1. Load inputs
# ---------------------------------------------------------------------------
def load_unique(path, sheet="Sheet1"):
    wb = openpyxl.load_workbook(path, read_only=True)
    ws = wb[sheet]
    rows = list(ws.iter_rows(values_only=True))
    wb.close()
    header = list(rows[0])
    names, seen = [], {}
    for i, h in enumerate(header):
        key = h if h is not None else f"col{i}"
        if key in seen:
            seen[key] += 1
            key = f"{key}#{seen[key]}"
        else:
            seen[key] = 1
        names.append(key)
    return pd.DataFrame(rows[1:], columns=names)

b102 = load_unique(os.path.join(BASE, "inputs", "基102-2002_原始结构脱敏输入.xlsx"))
ct = load_unique(os.path.join(BASE, "inputs", "基101-2002_原始结构脱敏输入.xlsx"))

with open(os.path.join(BASE, "inputs", "source_identity_index.json"), "r", encoding="utf-8") as f:
    idx = json.load(f)
recs = {r["source_row"]: r for r in idx["records"]}
assert len(recs) == len(b102) == 5922

b102["source_id"] = b102.index.map(lambda i: recs[i + 2]["source_id"])
b102["source_row"] = b102.index + 2

# ---------------------------------------------------------------------------
# 2. Classification
# ---------------------------------------------------------------------------
D44 = {"4411", "4412", "4417", "4430"}
OUT_IND = {"0511", "0539", "4690"}

st_id = b102["电站锅炉/燃气轮机编号"].notna()
ib_id = b102["工业锅炉编号"].notna()
ind_code = b102["行业类别代码"].astype(str)

decided, dispositions, reasons = [], [], []
for i in range(len(b102)):
    sid = b102["source_id"].iloc[i]
    if st_id.iloc[i]:
        decided.append("POWER_THERMAL"); dispositions.append("excluded_power_thermal")
        reasons.append("STATION_BOILER_DEVICE")
    elif ib_id.iloc[i]:
        if ind_code.iloc[i] in D44:
            decided.append("POWER_THERMAL"); dispositions.append("excluded_power_thermal")
            reasons.append("INDUSTRY_D44_POWER_THERMAL")
        elif ind_code.iloc[i] in OUT_IND:
            decided.append("OUT_OF_SCOPE"); dispositions.append("excluded_out_of_scope")
            reasons.append("INDUSTRY_NOT_IN_STANDARD_SCOPE")
        else:
            decided.append("INDUSTRIAL"); dispositions.append("in_scope")
            reasons.append("INDUSTRIAL_BOILER_DEVICE")
    else:
        decided.append("OUT_OF_SCOPE"); dispositions.append("excluded_out_of_scope")
        reasons.append("NO_DEVICE_IDENTIFIER")

b102["decided_target"] = decided
b102["disposition"] = dispositions
b102["decision_reason"] = reasons

n_ind = (b102["decided_target"] == "INDUSTRIAL").sum()
n_pow = (b102["decided_target"] == "POWER_THERMAL").sum()
n_out = (b102["decided_target"] == "OUT_OF_SCOPE").sum()
print(f"classification: INDUSTRIAL={n_ind} POWER_THERMAL={n_pow} OUT_OF_SCOPE={n_out}")

# ---------------------------------------------------------------------------
# 3. Emission factors (Appendix E Table E.7, g/kg fuel; gas fuels g/m3)
#    gas fuels are measured in m3 in the source data, and the gas EF rows are
#    identical to the explicitly g/m3 rows of Table D.1 (电力供应) -> g/m3.
# ---------------------------------------------------------------------------
E7 = {
    "COAL_PF":   dict(CO=2.0,   NOX=5.47, VOC=2.16),   # 煤粉炉
    "COAL_FB":   dict(CO=2.0,   NOX=7.5,  VOC=2.16),   # 流化床炉
    "COAL_AG":   dict(CO=15.0,  NOX=4.0,  VOC=2.16),   # 自动炉排层燃炉
    "COAL_MG":   dict(CO=124.3, NOX=3.8,  VOC=4.53),   # 手动炉排层燃炉
    "COKE":      dict(CO=2.0,   NOX=4.0,  VOC=0.04),
    "OTHER_COKE":dict(CO=2.0,   NOX=5.84, SO2=0.0, VOC=0.04, PM25=0.0, PM10=0.0, BC=0.0, OC=0.0),
    "NATURAL_GAS": dict(CO=1.3, NOX=2.09, SO2=0.0, VOC=0.12, PM25=0.03, PM10=0.03, BC=0.0, OC=0.0),
    "LNG":       dict(CO=0.36,  NOX=2.63, SO2=0.0, VOC=33.0, PM25=0.17, PM10=0.17, BC=0.02, OC=0.05),
    "LPG":       dict(CO=0.36,  NOX=2.63, SO2=0.0, VOC=33.0, PM25=0.17, PM10=0.17, BC=0.02, OC=0.05),
    "COKE_OVEN_GAS": dict(CO=1.3, NOX=0.96, SO2=0.0, VOC=0.02, PM25=0.03, PM10=0.03, BC=0.0, OC=0.0),
    "BF_GAS":    dict(CO=1.3,   NOX=0.13, SO2=0.0, VOC=0.05, PM25=0.03, PM10=0.03, BC=0.0, OC=0.0),
    "OTHER_GAS": dict(CO=1.3,   NOX=0.13, SO2=0.0, VOC=0.05, PM25=0.03, PM10=0.03, BC=0.0, OC=0.0),
    "REFINERY_GAS": dict(CO=0.0, NOX=0.53, SO2=0.0, VOC=0.0, PM25=0.0, PM10=0.0, BC=0.0, OC=0.0),
    "DIESEL":    dict(CO=0.6,   NOX=9.62, SO2=3.0, VOC=0.13, PM25=0.5,  PM10=0.5,  BC=0.14, OC=0.04),
    "FUEL_OIL":  dict(CO=0.6,   NOX=5.84, SO2=20.0, VOC=2.88, PM25=0.67, PM10=1.03, BC=0.04, OC=0.01),
    "CRUDE_OIL": dict(CO=0.6,   NOX=5.09, SO2=0.0, VOC=0.13, PM25=0.62, PM10=0.85, BC=0.04, OC=0.01),
    "OTHER_PETRO": dict(CO=0.6, NOX=5.84, SO2=0.0, VOC=0.13, PM25=0.62, PM10=0.85, BC=0.04, OC=0.01),
    "PETRO_COKE": dict(CO=0.6,  NOX=5.84, SO2=0.0, VOC=33.0, PM25=0.62, PM10=0.85, BC=0.04, OC=0.01),
}
GAS_UNIT_FUELS = {"NATURAL_GAS", "COKE_OVEN_GAS", "BF_GAS", "OTHER_GAS"}

# fuel type -> E7 key (or None if no EF in standard)
FUEL_MAP = {
    "一般烟煤": "COAL", "无烟煤": "COAL", "原煤": "COAL", "褐煤": "COAL",
    "其他洗煤": "COAL", "煤制品": "COAL",
    "焦炭": "COKE", "其他焦化产品": "OTHER_COKE",
    "天然气": "NATURAL_GAS", "液化天然气": "LNG", "液化石油气": "LPG",
    "焦炉煤气": "COKE_OVEN_GAS", "高炉煤气": "BF_GAS", "转炉煤气": "BF_GAS",
    "发生炉煤气": "OTHER_GAS",
    "炼厂干气": "REFINERY_GAS",
    "柴油": "DIESEL", "燃料油": "FUEL_OIL", "原油": "CRUDE_OIL",
    "其他石油制品": "OTHER_PETRO", "石油焦": "PETRO_COKE",
}
NO_EF_FUELS = {"生物燃料", "城市生活垃圾（用于燃料）", "工业废料（用于燃料）",
               "其他燃料", "润滑油", "煤矸石（用于燃料）"}

# Appendix C (industrial sector 采矿业、制造业、燃气生产和供应业) coal params
COAL_PARAMS = {
    "煤粉炉":        dict(sr=0.15, ar=0.25, f25=0.06,  f10=0.23,  fbc=0.002, foc=0.0),
    "流化床炉":      dict(sr=0.15, ar=0.40, f25=0.07,  f10=0.20,  fbc=0.006, foc=0.0),
    "自动炉排层燃炉": dict(sr=0.15, ar=0.85, f25=0.07,  f10=0.20,  fbc=0.200, foc=0.040),
    "手动炉排层燃炉": dict(sr=0.15, ar=0.85, f25=0.07,  f10=0.20,  fbc=0.200, foc=0.040),
}
FURNACE_MAP = {
    "煤粉炉": "煤粉炉", "循环流化床锅炉": "流化床炉",
    "链条炉": "自动炉排层燃炉", "其他层燃炉": "自动炉排层燃炉", "抛煤机炉": "自动炉排层燃炉",
}

# ---------------------------------------------------------------------------
# 4. Control efficiency (Appendix A Table A.1 + reported efficiencies)
# ---------------------------------------------------------------------------
def _class_eff(name, kind):
    """Map a process name to (Table A.1 class, method_label, SO2, NOX, PM25, PM25_10) or None."""
    n = "" if name is None else str(name)
    if kind == "脱硫（酸）设施":
        if "炉内脱硫" in n:
            if "双碱" in n: return ("双碱法", 80.0, None, None, None)
            if "钠碱" in n: return ("其他脱硫技术", 40.0, None, None, None)
            if "石灰" in n: return ("石灰石/石膏法", 80.0, None, None, None)
            if "循环流化床" in n or "烟气循环" in n: return ("烟气循环流化床法", 50.0, None, None, None)
            return ("炉内喷钙法", 50.0, None, None, None)
        if "双碱" in n: return ("双碱法", 80.0, None, None, None)
        if "石灰" in n: return ("石灰石/石膏法", 80.0, None, None, None)
        if "海水" in n: return ("海水法", 80.0, None, None, None)
        if "氧化镁" in n: return ("氧化镁法", 80.0, None, None, None)
        if "氨法" in n or "氨-硫铵" in n: return ("氨法", 80.0, None, None, None)
        if "烟气循环流化床" in n or "循环流化床" in n: return ("烟气循环流化床法", 50.0, None, None, None)
        if "喷钙" in n: return ("炉内喷钙法", 50.0, None, None, None)
        if "密相干" in n: return ("密相干法", 50.0, None, None, None)
        if "旋转喷雾" in n: return ("旋转喷雾干燥法", 50.0, None, None, None)
        if "钠碱" in n or "碱法" in n or "脱硫" in n: return ("其他脱硫技术", 40.0, None, None, None)
        return ("其他脱硫技术", 40.0, None, None, None)
    if kind == "除尘设施":
        if "电袋" in n: return ("电袋复合除尘法", None, None, 96.0, 99.0)
        if "袋式" in n or "布袋" in n: return ("袋式除尘法", None, None, 94.5, 95.0)
        if "湿式电除尘" in n or "高效静电" in n: return ("高效静电除尘法", None, None, 96.0, 99.0)
        if "静电" in n: return ("普通静电除尘法", None, None, 93.0, 98.0)
        if "湿" in n and ("喷淋" in n or "水浴" in n or "文丘里" in n or "水膜" in n or "湿式" in n or "湿法" in n):
            return ("湿式除尘法", None, None, 50.0, 56.1)
        if "多管旋风" in n: return ("多管旋风除尘法", None, None, 10.0, 70.0)
        if "旋风" in n or "机械" in n or "惯性" in n or "重力" in n or "管式" in n or "板式" in n:
            return ("机械式除尘法", None, None, 10.0, 19.2)
        return ("其他除尘技术", None, None, 10.0, 70.0)
    if kind == "脱硝设施":
        low = "低氮" in n
        scr = ("SCR" in n.upper()) or ("选择性催化还原" in n)
        sncr = ("SNCR" in n.upper()) or ("选择性非催化还原" in n)
        if low and scr: return ("低氮燃烧技术+选择性催化还原法", None, 64.0, None, None)
        if low and sncr: return ("低氮燃烧技术+选择性非催化还原法", None, 52.0, None, None)
        if scr: return ("选择性催化还原法", None, 42.0, None, None)
        if sncr: return ("选择性非催化还原法", None, 30.0, None, None)
        if low: return ("低氮燃烧技术", None, 22.0, None, None)
        return ("其他脱硝技术", None, 20.0, None, None)
    return None

def fac_eff(f):
    """Return (so2_eta, nox_eta, pm25_eta, pm10c_eta, method_label) for one GYGL facility."""
    kind = f.get("废气治理设施名称")
    rep = f.get("去除效率（%）")
    rep = None if rep is None or (isinstance(rep, float) and math.isnan(rep)) else rep
    rep_eta = None if rep is None else min(float(rep), 100.0) / 100.0
    cls = _class_eff(f.get("处理工艺名称"), kind)
    so2 = nox = pm25 = pm10c = None
    label = None
    if kind == "脱硫（酸）设施" and cls:
        label = cls[0]
        so2 = rep_eta if rep_eta is not None else cls[1] / 100.0
    elif kind == "除尘设施" and cls:
        label = cls[0]
        if rep_eta is not None:
            pm25 = pm10c = rep_eta
        else:
            pm25, pm10c = cls[2] / 100.0, cls[3] / 100.0
    elif kind == "脱硝设施" and cls:
        label = cls[0]
        nox = rep_eta if rep_eta is not None else cls[1] / 100.0
    elif kind == "除尘设施" and rep_eta is not None:
        label = "除尘设施(工艺未注明)"
        pm25 = pm10c = rep_eta
    elif kind == "脱硫（酸）设施" and rep_eta is not None:
        label = "脱硫设施(工艺未注明)"
        so2 = rep_eta
    elif kind == "脱硝设施" and rep_eta is not None:
        label = "脱硝设施(工艺未注明)"
        nox = rep_eta
    return so2, nox, pm25, pm10c, label

gygl = ct[ct["对应的排放口代码"] == "GYGL"].copy()
gygl["eff"] = pd.to_numeric(gygl["去除效率（%）"], errors="coerce")
fac_by_ent = {}
for _, f in gygl.iterrows():
    fac_by_ent.setdefault(f["统一社会信用代码"], []).append(f)

def control_eta(source_row):
    """Return dict poll -> (eta_fine, eta_coarse, method_label) for a source."""
    ent = source_row["统一社会信用代码"]
    so2 = nox = pm25 = pm10c = None
    labels = []
    for f in fac_by_ent.get(ent, []):
        s, n, p, pc, lab = fac_eff(f)
        if s is not None:
            so2 = max(so2 or 0.0, s)
            labels.append(lab)
        if n is not None:
            nox = max(nox or 0.0, n)
            labels.append(lab)
        if p is not None:
            pm25 = max(pm25 or 0.0, p)
            labels.append(lab)
        if pc is not None:
            pm10c = max(pm10c or 0.0, pc)
            labels.append(lab)
    low = source_row["是否采用低氮燃烧技术#2"]
    lownox = 1 if (isinstance(low, str) and low == "是") or low in (1, "1") else 0
    # low-NOx flag + plain SCR/SNCR -> combined values of Table A.1
    if lownox:
        scr_plain = sncr_plain = False
        for f in fac_by_ent.get(ent, []):
            if f.get("废气治理设施名称") == "脱硝设施" and f.get("去除效率（%）") is None:
                n_ = str(f.get("处理工艺名称") or "")
                if ("SCR" in n_.upper() or "选择性催化还原" in n_) and "低氮" not in n_:
                    scr_plain = True
                if ("SNCR" in n_.upper() or "选择性非催化还原" in n_) and "低氮" not in n_:
                    sncr_plain = True
        if scr_plain:
            nox = max(nox or 0.0, 0.64); labels.append("低氮燃烧技术+选择性催化还原法")
        elif sncr_plain:
            nox = max(nox or 0.0, 0.52); labels.append("低氮燃烧技术+选择性非催化还原法")
        else:
            nox = max(nox or 0.0, 0.22); labels.append("低氮燃烧技术")
    eta = {
        "SO2": (so2 if so2 is not None else 0.0),
        "NOX": (nox if nox is not None else 0.0),
        "CO": 0.0, "VOC": 0.0,
        "PM2.5": (pm25 if pm25 is not None else 0.0),
        "PM10": (pm25 if pm25 is not None else 0.0),
        "BC": (pm25 if pm25 is not None else 0.0),
        "OC": (pm25 if pm25 is not None else 0.0),
        "NH3": 0.0,
    }
    pm10coarse = pm10c if pm10c is not None else 0.0
    label = "、".join(sorted(set(labels))) if labels else "无"
    return eta, pm10coarse, label

# ---------------------------------------------------------------------------
# 5. Per-source pollutant computation
# ---------------------------------------------------------------------------
def get_comp(source_row, slot):
    """Return dict(active, e7key, furnace, value, unit, type, s_pct, a_pct) for a fuel slot."""
    if slot == "FUEL1":
        t = source_row["燃料一类型"]; v = source_row["燃料一消耗量"]; u = source_row["燃料一消耗量单位"]
        s = source_row["燃料一平均收到基含硫量"]; a = source_row["燃料一平均收到基灰分（%）"]
        mode = source_row["工业锅炉燃烧方式"]
    elif slot == "FUEL2":
        t = source_row["燃料二类型"]; v = source_row["燃料二消耗量"]; u = source_row["燃料二消耗量单位"]
        s = source_row["燃料二平均收到基含硫量"]; a = source_row["燃料二平均收到基灰分（%）"]
        mode = source_row["工业锅炉燃烧方式"]
    else:
        t = "其他燃料(未指明类型)"; v = source_row["其他燃料消耗总量（吨标准煤）"]; u = "吨标准煤"
        s = None; a = None; mode = source_row["工业锅炉燃烧方式"]
    try:
        v = float(v)
        if math.isnan(v): v = None
    except (TypeError, ValueError):
        v = None
    return dict(slot=slot, type=t, value=v, unit=u, s=s, a=a, mode=mode)

def comp_ef(comp, poll):
    """Return (ef_value, unit_g, param_id, mode_label, reason) for pollutant on component."""
    t = comp["type"]
    if t is None or str(t) == "nan" or str(t) == "":
        return None, None, None, None, "FUEL_TYPE_MISSING"
    if str(t) == "其他燃料(未指明类型)":
        return None, None, None, None, "OTHER_FUEL_TCE_TYPE_UNKNOWN"
    if t in NO_EF_FUELS:
        return None, None, None, None, "EF_NOT_IN_STANDARD_" + ("BIOMASS" if t == "生物燃料" else "FUEL")
    key = FUEL_MAP.get(t)
    if key is None:
        return None, None, None, None, "EF_NOT_IN_STANDARD_FUEL"
    # gas turbine device has no EF category in the standard
    if source_type_of(comp) == "燃气轮机":
        return None, None, None, None, "EF_NOT_IN_STANDARD_GAS_TURBINE"
    if key == "COAL":
        furnace = FURNACE_MAP.get(comp["mode"])
        if furnace is None:
            return None, None, None, None, "COAL_FURNACE_UNKNOWN"
        row = E7["COAL_" + {"煤粉炉": "PF", "流化床炉": "FB", "自动炉排层燃炉": "AG", "手动炉排层燃炉": "MG"}[furnace]]
        if poll in ("CO", "NOX", "VOC"):
            return row[poll], "g/kg", "EF_" + poll, "table_E7", None
        p = COAL_PARAMS[furnace]
        if poll == "SO2":
            s = to_f(comp["s"])
            if s is None: return None, None, None, None, "COAL_SULFUR_MISSING"
            ef = 2.0 * (s / 100.0) * (1 - p["sr"]) * 1000.0
            return ef, "g/kg", "EF_SO2", "material_balance_C1", None
        if poll == "PM2.5":
            a = to_f(comp["a"])
            if a is None: return None, None, None, None, "COAL_ASH_MISSING"
            ef = (a / 100.0) * (1 - p["ar"]) * p["f25"] * 1000.0
            return ef, "g/kg", "EF_PM25", "material_balance_C2", None
        if poll == "PM10":
            a = to_f(comp["a"])
            if a is None: return None, None, None, None, "COAL_ASH_MISSING"
            ef = (a / 100.0) * (1 - p["ar"]) * p["f10"] * 1000.0
            return ef, "g/kg", "EF_PM10", "material_balance_C2", None
        if poll == "BC":
            a = to_f(comp["a"])
            if a is None: return None, None, None, None, "COAL_ASH_MISSING"
            ef25 = (a / 100.0) * (1 - p["ar"]) * p["f25"] * 1000.0
            return ef25 * p["fbc"], "g/kg", "EF_BC", "material_balance_C3", None
        if poll == "OC":
            a = to_f(comp["a"])
            if a is None: return None, None, None, None, "COAL_ASH_MISSING"
            ef25 = (a / 100.0) * (1 - p["ar"]) * p["f25"] * 1000.0
            return ef25 * p["foc"], "g/kg", "EF_OC", "material_balance_C3", None
        return None, None, None, None, "EF_NOT_IN_STANDARD_POLLUTANT"
    if key == "COKE":
        row = E7["COKE"]
        if poll in ("CO", "NOX", "VOC"):
            return row[poll], "g/kg", "EF_" + poll, "table_E7", None
        # coke SO2/PM/BC/OC are 物料衡算 but Appendix C parameters are coal-only
        return None, None, None, None, "COKE_MB_PARAM_UNAVAILABLE"
    row = E7[key]
    if poll in row:
        unit = "g/m3" if key in GAS_UNIT_FUELS else "g/kg"
        return row[poll], unit, "EF_" + poll, "table_E7", None
    return None, None, None, None, "EF_NOT_IN_STANDARD_POLLUTANT"

_source_type_cache = {}
