def build_items():
    items = []
    ind = b102[b102["decided_target"] == "INDUSTRIAL"]
    for _, row in ind.iterrows():
        sid = row["source_id"]
        comps = []
        for slot in ("FUEL1", "FUEL2", "OTHER"):
            c = get_comp(row, slot)
            if c["type"] is None or str(c["type"]) == "nan":
                continue
            if c["value"] is None:
                continue
            if c["value"] <= 0:
                continue
            comps.append(c)
        # source-level control
        eta, pm10coarse, ctrl_label = control_eta(row)
        # activity state
        any_blank = False
        for slot in ("FUEL1", "FUEL2", "OTHER"):
            raw = row["燃料一消耗量"] if slot == "FUEL1" else (row["燃料二消耗量"] if slot == "FUEL2" else row["其他燃料消耗总量（吨标准煤）"])
            if raw is None or (isinstance(raw, float) and math.isnan(raw)):
                any_blank = True
        all_filled_zero = not any_blank and len(comps) == 0
        for poll in POLLUTANTS:
            if len(comps) == 0:
                if all_filled_zero:
                    st, gen, emis, rc = "not_involved", None, None, "FUEL_ACTIVITY_ZERO"
                else:
                    st, gen, emis, rc = "information_insufficient", None, None, "FUEL_ACTIVITY_MISSING"
                act, par, ctr = [], [], []
                items.append((sid, poll, st, rc, gen, emis, act, par, ctr, None, None, ctrl_label, "NA"))
                continue
            # per-component EF for this pollutant
            act, par, ctr = [], [], []
            gen = 0.0
            ef_ok = True
            reason = None
            method = "coefficient_E7"
            std_refs = set()
            for c in comps:
                _source_type_cache[id(c)] = str(row["工业锅炉类型"])
                ef, unit, pid, mode, rc = comp_ef(c, poll)
                act.append(dict(component_id=c["slot"], value=round(c["value"], 6), unit=c["unit"]))
                if ef is None:
                    par.append(dict(component_id=c["slot"], parameter_id=pid or "EF_" + poll,
                                    mode=mode or "unavailable", value=None, unit=unit))
                    ef_ok = False
                    reason = rc
                    # control record still aligned to component
                    ctr.append(dict(component_id=c["slot"], method="NA", efficiency=0.0,
                                    fine_efficiency=None, coarse_efficiency=None))
                    continue
                par.append(dict(component_id=c["slot"], parameter_id=pid, mode=mode,
                                value=round(ef, 6), unit=unit))
                mult = 10000.0 if unit == "g/m3" else 1000.0
                gen += c["value"] * mult * ef
                if mode == "material_balance_C1":
                    method = "material_balance"
                    std_refs.add("T/CSES 144-2024 公式(3)+附录C 表C.1")
                elif mode == "material_balance_C2":
                    method = "material_balance"
                    std_refs.add("T/CSES 144-2024 公式(4)+附录C 表C.2")
                elif mode == "material_balance_C3":
                    method = "material_balance"
                    std_refs.add("T/CSES 144-2024 公式(5)~公式(6)+附录C 表C.3")
                else:
                    std_refs.add("T/CSES 144-2024 附录E 表E.7")
                # control record per component
                if poll == "PM10":
                    ctr.append(dict(component_id=c["slot"], method=ctrl_label,
                                    efficiency=round(eta[poll], 6),
                                    fine_efficiency=round(eta[poll], 6),
                                    coarse_efficiency=round(pm10coarse, 6)))
                else:
                    ctr.append(dict(component_id=c["slot"], method=ctrl_label,
                                    efficiency=round(eta[poll], 6),
                                    fine_efficiency=None, coarse_efficiency=None))
            gen = gen / 1e6  # g -> t
            if not ef_ok:
                st, emis = "information_insufficient", None
            else:
                st = "calculated"
                emis = gen * (1.0 - eta[poll])
            if poll == "NH3" and ef_ok:
                st, gen, emis, reason = "information_insufficient", None, None, "NH3_EF_UNAVAILABLE"
            std_ref = "T/CSES 144-2024 §8.3.1 公式(2)" + ("; " + "; ".join(sorted(std_refs)) if std_refs else "")
            if poll in ("SO2", "NOX", "CO", "VOC", "PM2.5", "PM10", "BC", "OC", "NH3"):
                std_ref += "; 附录A 表A.1" if ctrl_label != "无" else ""
            items.append((sid, poll, st, reason, gen, emis, act, par, ctr, method, std_ref, ctrl_label, "NA"))
    return items

