{"content": "#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Validate output CSVs and JSON per task contract."""
import json, csv, os, sys

BASE = "/Users/wushuo/Desktop/环境学院论文/固定燃烧源清单经验缺失处置实验/实验结果/02_实验A_端到端清单编制/01_工业锅炉/03_通用工具调用型Agent/R2"
OUT = os.path.join(BASE, "outputs")
errors, warns = [], []

def read_csv(name):
    with open(os.path.join(OUT, name), encoding="utf-8", newline="") as f:
        return list(csv.DictReader(f))

# ---- 1. source_decisions.csv ----
sd = read_csv("source_decisions.csv")
print("source_decisions rows:", len(sd), "cols:", list(sd[0].keys()))
assert list(sd[0].keys()) == ["source_id", "requested_target", "decided_target", "disposition", "reason_code"], "cols"
sids = [r["source_id"] for r in sd]
if len(set(sids)) != len(sids): errors.append("source_decisions: duplicate source_id")
if any(r["requested_target"] != "INDUSTRIAL" for r in sd): errors.append("requested_target != INDUSTRIAL")
allowed = {"INDUSTRIAL", "POWER_THERMAL", "OUT_OF_SCOPE"}
if any(r["decided_target"] not in allowed for r in sd): errors.append("bad decided_target")
from collections import Counter
print("decided_target:", dict(Counter(r["decided_target"] for r in sd)))
print("disposition:", dict(Counter(r["disposition"] for r in sd)))

# ---- 2. generic_inventory_items.csv ----
inv = read_csv("generic_inventory_items.csv")
print("\ngeneric_inventory_items rows:", len(inv), "cols:", list(inv[0].keys()))
assert list(inv[0].keys()) == ["source_id", "target", "pollutant", "status", "method",
                               "activity_record_json", "parameter_record_json",
                               "control_record_json", "generation_t", "emission_t",
                               "standard_reference", "reason_code"]
pairs = [(r["source_id"], r["pollutant"]) for r in inv]
if len(set(pairs)) != len(pairs): errors.append("inventory: duplicate source x pollutant")
if any(r["target"] != "INDUSTRIAL" for r in inv): errors.append("target != INDUSTRIAL")
st_allowed = {"calculated", "not_involved", "information_insufficient", "source_data_invalid"}
print("status:", dict(Counter(r["status"] for r in inv)))
if any(r["status"] not in st_allowed for r in inv): errors.append("bad status")
poll_set = {"SO2","NOX","CO","VOC","PM2.5","PM10","BC","OC","NH3"}
if any(r["pollutant"] not in poll_set for r in inv): errors.append("bad pollutant")

ncalc = sum(1 for r in inv if r["status"] == "calculated")
nins = sum(1 for r in inv if r["status"] == "information_insufficient")
nninv = sum(1 for r in inv if r["status"] == "not_involved")

# JSON + array alignment + non-negativity
bad_json = 0; bad_align = 0; bad_neg = 0; bad_eff = 0; bad_pm10 = 0
for r in inv:
    for k in ("activity_record_json", "parameter_record_json", "control_record_json"):
        try:
            v = json.loads(r[k])
        except Exception:
            bad_json += 1; errors.append(f"bad json in {r['source_id']} {r['pollutant']} {k}"); break
        if not isinstance(v, list):
            bad_json += 1; errors.append(f"not array {r['source_id']} {r['pollutant']} {k}")
    else:
        a, p, c = (json.loads(r["activity_record_json"]), json.loads(r["parameter_record_json"]), json.loads(r["control_record_json"]))
        if not (len(a) == len(p) == len(c)):
            bad_align += 1; errors.append(f"array length mismatch {r['source_id']} {r['pollutant']}")
        else:
            for j in range(len(a)):
                if a[j]["component_id"] != p[j]["component_id"] or a[j]["component_id"] != c[j]["component_id"]:
                    bad_align += 1; errors.append(f"component_id mismatch {r['source_id']} {r['pollutant']} idx{j}")
        # required fields
        for j, arr in ((0, a), (1, p), (2, c)):
            need = ["component_id","value","unit"] if j == 0 else (["component_id","parameter_id","mode","value","unit"] if j == 1 else ["component_id","method","efficiency","fine_efficiency","coarse_efficiency"])
            for e in arr:
                for fld in need:
                    if fld not in e:
                        errors.append(f"missing field {fld} in {r['source_id']} {r['pollutant']} arr{j}")
    # numeric checks
    for col in ("generation_t", "emission_t"):
        v = r[col]
        if v != "":
            try:
                fv = float(v)
                if fv < 0: bad_neg += 1; errors.append(f"negative {col} {r['source_id']} {r['pollutant']}")
            except ValueError:
                errors.append(f"non-numeric {col} {r['source_id']} {r['pollutant']}")
    # status-value consistency
    if r["status"] == "calculated" and (r["generation_t"] == "" or r["emission_t"] == ""):
        errors.append(f"calculated but empty value {r['source_id']} {r['pollutant']}")
    if r["status"] != "calculated" and (r["generation_t"] != "" or r["emission_t"] != ""):
        errors.append(f"non-calculated with value {r['source_id']} {r['pollutant']}")
    # PM10 fine/coarse both required
    if r["pollutant"] == "PM10":
        for e in json.loads(r["control_record_json"]):
            if e["fine_efficiency"] is None or e["coarse_efficiency"] is None:
                bad_pm10 += 1; errors.append(f"PM10 missing fine/coarse {r['source_id']}")
    # non-PM10 efficiency present
    if r["pollutant"] != "PM10" and r["status"] in ("calculated", "information_insufficient"):
        for e in json.loads(r["control_record_json"]):
            if e["efficiency"] is None:
                bad_eff += 1; errors.append(f"efficiency None {r['source_id']} {r['pollutant']}")
print("json bad:", bad_json, "align bad:", bad_align, "neg:", bad_neg, "eff none:", bad_eff, "pm10 bad:", bad_pm10)

# coverage: all INDUSTRIAL sources have 9 rows
src_inv = set(r["source_id"] for r in inv)
sd_ind = set(r["source_id"] for r in sd if r["decided_target"] == "INDUSTRIAL")
if src_inv != sd_ind:
    errors.append(f"inventory sources {len(src_inv)} != INDUSTRIAL decided {len(sd_ind)}; missing {len(sd_ind - src_inv)}")
else:
    print("inventory covers all INDUSTRIAL sources:", len(src_inv))

# ---- 3. generic_source_disposition.csv ----
gdisp = read_csv("generic_source_disposition.csv")
print("\ngeneric_source_disposition rows:", len(gdisp), "cols:", list(gdisp[0].keys()))
assert list(gdisp[0].keys()) == ["source_id", "target", "disposition", "reason_code"]
gids = [r["source_id"] for r in gdisp]
if len(set(gids)) != len(gids): errors.append("disposition: dup source_id")
if set(gids) != set(sids): errors.append("disposition source coverage mismatch")
print("disposition:", dict(Counter(r["disposition"] for r in gdisp)))

# ---- 4. generic_exception_list.csv ----
exc = read_csv("generic_exception_list.csv")
print("\ngeneric_exception_list rows:", len(exc), "cols:", list(exc[0].keys()))
assert list(exc[0].keys()) == ["exception_id", "source_id", "pollutant", "root_cause", "action_required"]
eids = [r["exception_id"] for r in exc]
if len(set(eids)) != len(eids): errors.append("exception: dup id")
for r in exc:
    if r["source_id"] not in set(sids):
        errors.append(f"exception source not in candidates: {r['source_id']}")
print([r["exception_id"] for r in exc])

# ---- 5. run summary ----
with open(os.path.join(OUT, "generic_run_summary.json"), encoding="utf-8") as f:
    summ = json.load(f)
print("\nsummary keys:", list(summ.keys()))
print("processed_source_count:", summ["processed_source_count"], "item_count:", summ["inventory_item_count"], "status_counts:", summ["status_counts"])
if summ["processed_source_count"] != 5922: errors.append("summary processed count != 5922")
if summ["inventory_item_count"] != len(inv): errors.append("summary item count mismatch")
if summ["status_counts"] != {r["status"] for r in inv} and summ["status_counts"] != dict(Counter(r["status"] for r in inv)):
    errors.append("summary status counts mismatch")

print("\nERRORS:", len(errors))
for e in errors[:40]:
    print(" -", e)
print("done")
